// The "Learn with sample data" project: BIForge's own synthetic cycle-shop data (app/src-tauri/sample, generated by
// tools/sample-data/generate.mjs), imported through the normal import path, with relationships, measures and a
// report page. Nothing here is Microsoft sample content.
import { agg, column, measure } from "../report/fields";
import { addMeasure } from "../model/ops";
import { addRelationship } from "../model/relationships";
import { addPage, addVisual } from "../report/reportOps";
import { listPageNames } from "../report/visualDoc";
import type { Session } from "./session";

const TABLES = ["Date", "Customer", "Product", "Sales"] as const;

export const SAMPLE_MEASURES: [string, string][] = [
  ["Sales Amount", "SUMX(Sales, Sales[Quantity] * Sales[UnitPrice])"],
  ["Units Sold", "SUM(Sales[Quantity])"],
  ["Orders", "COUNTROWS(Sales)"],
  ["Average Order Value", "DIVIDE([Sales Amount], [Orders])"],
];

export async function createSampleProject(s: Session, root: string, name: string): Promise<void> {
  if (!s.io.writeSampleData) throw new Error("The sample data cannot be written in this environment.");
  if (!s.engine) throw new Error("The data engine is not available.");
  await s.newProject(root, name);
  const paths = await s.io.writeSampleData(root);
  for (const [i, table] of TABLES.entries()) await s.importTable(table, { kind: "csv", path: paths[i], delimiter: ",", header: true });
  s.store.transact("Sample model", (p) => {
    addRelationship(p, { fromTable: "Sales", fromColumn: "OrderDate", toTable: "Date", toColumn: "Date" });
    addRelationship(p, { fromTable: "Sales", fromColumn: "CustomerKey", toTable: "Customer", toColumn: "CustomerKey" });
    addRelationship(p, { fromTable: "Sales", fromColumn: "ProductKey", toTable: "Product", toColumn: "ProductKey" });
    for (const [n, e] of SAMPLE_MEASURES) addMeasure(p, "Sales", n, e);
    const page = listPageNames(p)[0] ?? addPage(p, "Overview");
    const at = (x: number, y: number, width: number, height: number) => ({ x, y, width, height });
    addVisual(p, page, "slicer", { position: at(20, 20, 200, 120), fields: [{ role: "Values", field: column("Customer", "Region") }] });
    addVisual(p, page, "card", { position: at(240, 20, 200, 120), fields: [{ role: "Values", field: measure("Sales", "Sales Amount") }] });
    addVisual(p, page, "card", { position: at(460, 20, 200, 120), fields: [{ role: "Values", field: measure("Sales", "Orders") }] });
    addVisual(p, page, "clusteredColumnChart", { position: at(20, 160, 420, 300), fields: [{ role: "Category", field: column("Product", "Category") }, { role: "Y", field: measure("Sales", "Sales Amount") }] });
    addVisual(p, page, "lineChart", { position: at(460, 160, 440, 300), fields: [{ role: "Category", field: column("Date", "YearMonth") }, { role: "Y", field: measure("Sales", "Sales Amount") }] });
    addVisual(p, page, "tableEx", { position: at(20, 480, 880, 200), fields: [{ role: "Values", field: column("Product", "Product") }, { role: "Values", field: agg("Sales", "Quantity", 0) }, { role: "Values", field: measure("Sales", "Sales Amount") }] });
  });
  await s.save();
}
